import { Hct, argbFromHex } from "@material/material-color-utilities";

export function normalizeHex(value) {
  let hex = String(value || "").trim();
  if (!hex) return null;
  if (!hex.startsWith("#")) hex = `#${hex}`;
  if (/^#[0-9a-f]{3}$/i.test(hex)) hex = `#${[...hex.slice(1)].map(c => c + c).join("")}`;
  return /^#[0-9a-f]{6}$/i.test(hex) ? hex.toUpperCase() : null;
}
export function rgb(hex) { const v = normalizeHex(hex) || "#000000"; return { r: parseInt(v.slice(1, 3), 16), g: parseInt(v.slice(3, 5), 16), b: parseInt(v.slice(5, 7), 16) }; }
export function hsl(hex) {
  let { r, g, b } = rgb(hex); r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b), delta = max - min;
  let h = 0, s = 0, l = (max + min) / 2;
  if (delta) { s = delta / (1 - Math.abs(2 * l - 1)); h = max === r ? ((g - b) / delta) % 6 : max === g ? (b - r) / delta + 2 : (r - g) / delta + 4; h = (h * 60 + 360) % 360; }
  return { h, s: s * 100, l: l * 100 };
}
export function hct(hex) { return Hct.fromInt(argbFromHex(normalizeHex(hex) || "#000000")); }
export function metadata(hex) { const c = rgb(hex), hs = hsl(hex), hc = hct(hex); return { rgb: `rgb(${c.r}, ${c.g}, ${c.b})`, hsl: `H ${Math.round(hs.h)} · S ${Math.round(hs.s)} · L ${Math.round(hs.l)}`, hct: `H ${Math.round(hc.hue)} · C ${Math.round(hc.chroma)} · T ${Math.round(hc.tone)}` }; }
const titleCase = filename => (filename.replace(/\.[^.]+$/, "").replace(/[-_]+/g, " ").trim() || "Uploaded Palette").replace(/\b\w/g, c => c.toUpperCase());
function csvCells(line) { const cells = []; let cell = "", quoted = false; for (let i = 0; i < line.length; i++) { const ch = line[i]; if (ch === '"' && quoted && line[i + 1] === '"') { cell += '"'; i++; } else if (ch === '"') quoted = !quoted; else if (ch === "," && !quoted) { cells.push(cell.trim()); cell = ""; } else cell += ch; } cells.push(cell.trim()); return cells; }
function csvRecords(text) { const records = []; let field = "", row = [], quoted = false; text = text.replace(/^\uFEFF/, ""); for (let i = 0; i < text.length; i++) { const ch = text[i]; if (ch === '"' && quoted && text[i + 1] === '"') { field += '"'; i++; } else if (ch === '"') quoted = !quoted; else if (ch === "," && !quoted) { row.push(field.trim()); field = ""; } else if ((ch === "\n" || ch === "\r") && !quoted) { if (ch === "\r" && text[i + 1] === "\n") i++; row.push(field.trim()); if (row.some(Boolean)) records.push(row); row = []; field = ""; } else field += ch; } row.push(field.trim()); if (row.some(Boolean)) records.push(row); return records; }
function hexFromText(text) { const match = String(text).match(/#[0-9a-f]{3}(?:[0-9a-f]{3})?\b/i) || String(text).match(/\b[0-9a-f]{6}\b/i); if (match) return normalizeHex(match[0]); const rgbMatch = String(text).match(/rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)/i); if (!rgbMatch) return null; const values = rgbMatch.slice(1).map(Number); return values.every(v => v <= 255) ? `#${values.map(v => v.toString(16).padStart(2, "0")).join("")}`.toUpperCase() : null; }
export function csvRows(text, filename) { const rows = csvRecords(text); if (!rows.length) return []; const headers = rows.shift().map(x => x.toLowerCase().trim()); const find = names => headers.findIndex(h => names.some(n => h === n || h.startsWith(n + " "))); const valueIndex = find(["hex", "color", "colour", "code", "value", "rgb"]), nameIndex = find(["name", "color name", "colour name", "token", "role"]), groupIndex = find(["group", "brand", "palette", "collection"]), layerIndex = find(["layer"]); return rows.map((cells, i) => { const hex = hexFromText(valueIndex >= 0 ? cells[valueIndex] : cells.join(" ")); return hex ? { group: cells[groupIndex] || titleCase(filename), name: cells[nameIndex] || `Color ${i + 1}`, hex, layer: cells[layerIndex] || "Generated" } : null; }).filter(Boolean); }
export function textRows(text, filename) { const found = [], seen = new Set(); const regex = /#[0-9a-f]{3}(?:[0-9a-f]{3})?\b|rgb\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*\)/gi; for (const match of text.matchAll(regex)) { const hex = hexFromText(match[0]); if (!hex || seen.has(hex)) continue; seen.add(hex); const before = text.slice(Math.max(0, match.index - 72), match.index).split(/\n/).pop().replace(/[^A-Za-z0-9 /_.-]+/g, " ").trim().replace(/[-:]$/, ""); found.push({ group: titleCase(filename), name: before || `Color ${found.length + 1}`, hex, layer: "Generated" }); } return found; }
export async function extractFile(file) { if (/\.csv$/i.test(file.name)) return csvRows(await file.text(), file.name); if (/\.pdf$/i.test(file.name)) { const pdfjs = await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs"); pdfjs.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs"; const pdf = await pdfjs.getDocument({ data: await file.arrayBuffer() }).promise; let text = ""; for (let i = 1; i <= pdf.numPages; i++) { const page = await pdf.getPage(i), content = await page.getTextContent(); text += content.items.map(item => item.str).join(" ") + "\n"; } return textRows(text, file.name); } throw new Error("Choose a CSV or PDF file."); }
export const modeInfo = { rgb: ["RGB Cube", "RGB plots red, green, and blue on three axes."], hsl: ["HSL Cylinder", "HSL plots hue around the ring, saturation outward, and lightness vertically."], hct: ["HCT Color Space", "HCT plots perceptual hue around the ring, chroma outward, and tone vertically."] };
export function position(color, mode) { if (mode === "rgb") { const c = rgb(color.hex); return { x: c.r / 255 - .5, y: c.g / 255 - .5, z: c.b / 255 - .5, label: `R ${c.r} · G ${c.g} · B ${c.b}` }; } const c = mode === "hsl" ? hsl(color.hex) : hct(color.hex); const hue = mode === "hsl" ? c.h : c.hue, radial = mode === "hsl" ? c.s / 100 * .62 : Math.min(c.chroma / 150, 1) * .62, vertical = mode === "hsl" ? c.l / 100 - .5 : c.tone / 100 - .5, angle = (hue - 90) * Math.PI / 180; return { x: Math.cos(angle) * radial, y: vertical, z: Math.sin(angle) * radial, label: mode === "hsl" ? `H ${Math.round(c.h)} · S ${Math.round(c.s)} · L ${Math.round(c.l)}` : `H ${Math.round(c.hue)} · C ${Math.round(c.chroma)} · T ${Math.round(c.tone)}` }; }
export function project(point, angles, zoom) { let { x, y, z } = point; const [rx, ry, rz] = [angles.x, angles.y, angles.z].map(v => v * Math.PI / 180); let a = x * Math.cos(rz) - y * Math.sin(rz), b = x * Math.sin(rz) + y * Math.cos(rz); x = a * Math.cos(ry) - z * Math.sin(ry); z = a * Math.sin(ry) + z * Math.cos(ry); y = b * Math.cos(rx) - z * Math.sin(rx); z = b * Math.sin(rx) + z * Math.cos(rx); const scale = 390 * zoom / (1.9 + z); return { x: 500 + x * scale, y: 350 - y * scale, z }; }
export const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z);
